    PatternRuleSpec("UVM040", "uvm_no_missing_super_connect", "Require super.connect_phase when connect_phase exists.", "Call super.connect_phase(phase) in connect_phase.", r"function\s+void\s+connect_phase\s*\(", "warning", "required_file_if", r"super\.connect_phase\s*\(\s*phase\s*\)"),
