    PatternRuleSpec("UVM043", "uvm_no_analysis_imp_write_empty", "Discourage empty analysis write methods.", "Implement analysis write methods or remove the unused analysis imp.", r"function\s+void\s+write\s*\([^)]*\)\s*;\s*endfunction", "warning"),
